#include <stdio.h>
#include <stdlib.h>
int main(void)
{
    const char *mode = getenv("APP_MODE");
    if (mode == NULL || mode[0] == '\0') mode = "standard";
    printf("mode=%s\n", mode);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
static void report_shutdown(void) { puts("normal termination handler ran"); }
int main(void)
{
    if (atexit(report_shutdown) != 0) { fputs("registration failed\n", stderr); return EXIT_FAILURE; }
    puts("program work completed");
    return EXIT_SUCCESS;
}
